# J. S. Bach, The Musical Offering, BWV 1079 (1747)
# Canon a 2 per augmentationem, contrario motu
# A realization with simplified ornaments and a closing cadence.
# Score reference
# https://archive.schillerinstitute.com/fid_97-01/984_sub_moral_appen_PDFs/chapter-4.PDF
# Pitch and timing reference
# https://github.com/x2yzen/x2yzen.github.io/blob/c5c6926832837184a379c82aecd38703ca088622/vitrine/canon_per_augmentationem_vitrine_pbr.html
{12edo}
{key <- C minor}

# Each row contains a pitch (or niente for a rest) and a duration in beats.
let subject <- [
  (niente, 0.75beat) (C, 0.125beat) (D, 0.125beat) (Eb, 0.75beat) (F, 0.25beat) (G, 1.5beat) (niente, 0.125beat) (F, 0.125beat) (Eb, 0.125beat) (D, 0.125beat)
  (C, 0.75beat) (`Bb, 0.25beat) (`Ab, 0.75beat) (`G, 0.25beat) (`F, 0.625beat) (`C, 0.125beat) (`D, 0.125beat) (`E, 0.125beat) (`F, 0.75beat) (`Ab, 0.25beat)
  (`G, 1beat) (niente, 1.75beat) (Eb, 0.25beat) (D, 0.75beat) (C, 0.25beat)
  (D, 0.75beat) (`A, 0.25beat) (`B, 0.75beat) (C, 0.25beat) (`B, 0.75beat) (`G, 0.25beat) (`A, 0.75beat) (`B, 0.25beat)
  (C, 0.75beat) (`G, 0.25beat) (C, 0.75beat) (`Bb, 0.25beat) (`Ab, 0.75beat) (`Eb, 0.25beat) (`Ab, 0.75beat) (`G, 0.25beat)
  (`F, 1.5beat) (niente, 0.125beat) (`G, 0.125beat) (`F, 0.125beat) (`E, 0.125beat) (`F, 0.75beat) (`G, 0.125beat) (`Ab, 0.125beat) (`D, 0.75beat) (`Eb, 0.125beat) (`F, 0.125beat)
  (`G, 1.5beat) (`A, 0.125beat) (`B, 0.125beat) (D, 0.125beat) (F, 0.125beat) (Ab, 0.625beat) (G, 0.125beat) (F, 0.125beat) (E_, 0.125beat) (F, 0.75beat) (`B, 0.25beat)
  (C, 0.625beat) (`C, 0.125beat) (`D, 0.125beat) (`Eb, 0.125beat) (`F, 1.25beat) (`D, 0.25beat) (`Eb, 0.25beat) (`F, 0.25beat) (`G, 0.25beat) (`Ab, 0.25beat) (`G, 0.25beat) (`F, 0.25beat)
]

fn contrary(tone) {
  # Map the subject’s opening C to G and reverse intervals from C.
  # Keep the E-flats at the minor third in both registers.
  let reflected <- G - (tone - C)
  if (tone @eq Eb) { reflected <- Eb }
  if (tone @eq `Eb) { reflected <- eb }
  ret reflected
}

fn playLine(line: container, stretch: ratio <- 1/1, inverted: boolean <- false) {
  ret for (event of line) {
    let tone <- event[0]
    let span <- stretch * event[1]
    if (@not tone) { fit(., span) }
    elif (inverted) { fit(contrary(tone), span) }
    else { fit(tone, span) }
  }
}
